import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seed=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==2: seed=(r,c)
    filled=set()
    def fill(r,c): out[r][c]=2; filled.add((r,c))
    # process row by row from seed row down
    for r in range(seed[0],h):
        newv=[]
        rowfill=sorted(c for (rr,c) in filled if rr==r)
        for c in rowfill:
            if r+1<h:
                if g[r+1][c]!=8:
                    if (r+1,c) not in filled: newv.append(c)
                else:
                    # spread horizontally in row r from c
                    for d in (-1,1):
                        cc=c
                        while 0<=cc+d<w:
                            cc+=d
                            if (r,cc) not in filled:
                                fill(r,cc)
                            if r+1<h and g[r+1][cc]!=8:
                                break
        for c in newv: fill(r+1,c)
    return out

